SourceCode.Declaration:
/// <summary>
/// Process definition for Barcode Registration
/// </summary>
class MwmsProcessRegisterBarcode extends TFMProcess
{
}

Method.Source:
protected void new()
{
    TFMLogicBlockItemInfo           infoBlock = new TFMLogicBlockItemInfo();
    MwmsLogicBlockRegisterBarcode   regBarcode= MwmsLogicBlockRegisterBarcode::Construct();
    processName = TFMConstants::RegisterBarcode();
    super();
    this.addBlock(infoBlock);
    this.addBlock(regBarcode);
    this.linkBlocks(infoBlock, regBarcode, '1', '1');
}
